import{_ as s}from"./chunks/ArticleMetadata.TT7jIO3o.js";import{_ as n,D as l,o as d,c as h,I as c,w as p,k as o,a as g,R as u,b,e as m}from"./chunks/framework.FHZ5yb6k.js";import"./chunks/md5.0oexlRJv.js";const B=JSON.parse('{"title":"IDEA 的使用技巧","description":"","frontmatter":{"title":"IDEA 的使用技巧","date":"2026/07/22","categories":["工具"],"tags":["IDEA","Java","开发工具","JetBrains"]},"headers":[],"relativePath":"categories/tools/开发工具/02-IDEA.md","filePath":"categories/tools/开发工具/02-IDEA.md","lastUpdated":1784697030000}'),k={name:"categories/tools/开发工具/02-IDEA.md"},D=o("h1",{id:"我的-intellij-idea-配置与插件清单",tabindex:"-1"},[g("我的 IntelliJ IDEA 配置与插件清单 "),o("a",{class:"header-anchor",href:"#我的-intellij-idea-配置与插件清单","aria-label":'Permalink to "我的 IntelliJ IDEA 配置与插件清单"'},"​")],-1),q=u('<blockquote><p>从 Eclipse 转到 IntelliJ IDEA 已经好几年了，当初听人说 &quot;用过就回不去&quot; 还不信，现在嘛……只能说真香。这篇文章不是官方文档搬运，纯粹是我自己日常使用的配置和插件记录，希望能给同样用 IDEA 的你一些参考。</p></blockquote><hr><h2 id="一、我装了哪些-jetbrains-家的-ide" tabindex="-1">一、我装了哪些 JetBrains 家的 IDE <a class="header-anchor" href="#一、我装了哪些-jetbrains-家的-ide" aria-label="Permalink to &quot;一、我装了哪些 JetBrains 家的 IDE&quot;">​</a></h2><p>说起来有点多，但每个都有明确的用途：</p><table><thead><tr><th>IDE</th><th>主要用途</th></tr></thead><tbody><tr><td><strong>IntelliJ IDEA Ultimate</strong></td><td>Java / Spring Boot 主力开发（日常待的时间最长）</td></tr><tr><td><strong>GoLand</strong></td><td>Go 微服务和工具开发</td></tr><tr><td><strong>PyCharm</strong></td><td>Python 数据处理、脚本编写</td></tr><tr><td><strong>DataGrip</strong></td><td>数据库查询和管理，查数据、写 SQL 都在这里</td></tr></tbody></table><p>同一个账号下这几个 IDE 的配置和快捷键是通用的，切换起来没什么割裂感。</p><hr><h2 id="二、一些我觉得值得改的设置" tabindex="-1">二、一些我觉得值得改的设置 <a class="header-anchor" href="#二、一些我觉得值得改的设置" aria-label="Permalink to &quot;二、一些我觉得值得改的设置&quot;">​</a></h2><h3 id="主题与外观" tabindex="-1">主题与外观 <a class="header-anchor" href="#主题与外观" aria-label="Permalink to &quot;主题与外观&quot;">​</a></h3><p>颜色主题用的 <strong>Dark</strong>（经典暗色），也是 JetBrains 默认的，看久了不累。新 UI（New UI）我已经开了——<code>ide.experimental.ui = true</code>，界面更清爽，图标更简洁，推荐试试。</p><h3 id="jvm-内存" tabindex="-1">JVM 内存 <a class="header-anchor" href="#jvm-内存" aria-label="Permalink to &quot;JVM 内存&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span>-Xmx6096m</span></span></code></pre></div><p>我给了 6G 左右。IDEA 本身比较吃内存，特别是打开多个大项目的时候，默认的 2G 会频繁触发 GC 导致卡顿。如果你的机器内存够（16G+），建议至少给 4G。</p><blockquote><p>设置位置：<code>Help → Edit Custom VM Options</code></p></blockquote><h3 id="编辑器行为" tabindex="-1">编辑器行为 <a class="header-anchor" href="#编辑器行为" aria-label="Permalink to &quot;编辑器行为&quot;">​</a></h3><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#8DDB8C;">option</span><span style="--shiki-light:#6F42C1;--shiki-dark:#6CB6FF;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;ADD_UNAMBIGIOUS_IMPORTS_ON_THE_FLY&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#6CB6FF;"> value</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;"> /&gt;</span></span></code></pre></div><p><strong>自动添加明确的导入</strong>。写代码时如果引用了一个类且没有歧义，IDEA 会自动帮你加上 import 语句。不用每次都手动 <code>Alt+Enter</code> 去选，写起代码来流畅很多。</p><h3 id="语言和地区" tabindex="-1">语言和地区 <a class="header-anchor" href="#语言和地区" aria-label="Permalink to &quot;语言和地区&quot;">​</a></h3><p>我切到了中文界面。不是说英文不好，而是有些配置项和报错信息用中文看确实更快，尤其是一些比较偏门的选项——英文单词认识但不知道对应哪个功能的情况还挺常见的。</p><h3 id="退出确认" tabindex="-1">退出确认 <a class="header-anchor" href="#退出确认" aria-label="Permalink to &quot;退出确认&quot;">​</a></h3><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#8DDB8C;">option</span><span style="--shiki-light:#6F42C1;--shiki-dark:#6CB6FF;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;confirmExit&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#6CB6FF;"> value</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;false&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;"> /&gt;</span></span></code></pre></div><p>关掉退出确认。IDEA 启动本来就不慢，万一不小心按到 Quit 也不会耽误事。</p><h3 id="git-配置" tabindex="-1">Git 配置 <a class="header-anchor" href="#git-配置" aria-label="Permalink to &quot;Git 配置&quot;">​</a></h3><p>打开即可，没啥可折腾的——Git 凭据助手开了就行。提交、推送、拉取这些 IDEA 默认就做得很好。</p><hr><h2 id="三、插件篇——哪些我装了并且一直在用" tabindex="-1">三、插件篇——哪些我装了并且一直在用 <a class="header-anchor" href="#三、插件篇——哪些我装了并且一直在用" aria-label="Permalink to &quot;三、插件篇——哪些我装了并且一直在用&quot;">​</a></h2><p>以下是 <code>~Library/Application Support/JetBrains/IntelliJIdea2024.3/plugins/</code> 里真实存在且我日常在用的插件，按场景分类说说为什么装它们。</p><h3 id="🌱-java-spring-生态" tabindex="-1">🌱 Java / Spring 生态 <a class="header-anchor" href="#🌱-java-spring-生态" aria-label="Permalink to &quot;🌱 Java / Spring 生态&quot;">​</a></h3><table><thead><tr><th>插件</th><th>为什么装</th></tr></thead><tbody><tr><td><strong>MybatisX</strong></td><td>写 MyBatis 项目必备。Mapper 接口和 XML 文件之间可以互相跳转，还能一键生成代码。配合<code>Free MyBatis Tool</code> 一起用，找 SQL、看参数映射基本不用切文件</td></tr><tr><td><strong>MavenHelper</strong></td><td>右侧栏直接运行 Maven 命令、查看依赖树、排除冲突依赖。排查依赖冲突时比在终端敲<code>mvn dependency:tree</code> 快太多了</td></tr><tr><td><strong>GenerateAllSetter</strong></td><td>一个 Bean 有十几个字段需要 set 的时候，一键生成所有 setter 调用。写单元测试或组装数据时能省不少重复劳动</td></tr><tr><td><strong>Generate All Getter And Setter</strong></td><td>看名字就知道了，生成类字段的 getter/setter</td></tr><tr><td><strong>pojo2json</strong></td><td>根据 POJO 类的字段结构快速生成 JSON 示例，写接口文档或者构造测试数据的时候很方便</td></tr><tr><td><strong>jclasslib</strong></td><td>看<code>.class</code> 文件的字节码信息，研究 JVM、分析编译结果时偶尔会用</td></tr><tr><td><strong>Lombook Plugin</strong></td><td>自带捆绑的，不用说了，用 Lombok 就得装它</td></tr></tbody></table><h3 id="🌐-微服务-分布式" tabindex="-1">🌐 微服务 &amp; 分布式 <a class="header-anchor" href="#🌐-微服务-分布式" aria-label="Permalink to &quot;🌐 微服务 &amp; 分布式&quot;">​</a></h3><table><thead><tr><th>插件</th><th>为什么装</th></tr></thead><tbody><tr><td><strong>spring-dubbo</strong></td><td>Dubbo 服务开发支持，接口定义和消费者、提供者之间的跳转</td></tr><tr><td><strong>spring-websocket</strong></td><td>WebSocket 端点开发辅助</td></tr><tr><td><strong>bigdatatools-flink</strong></td><td>Flink 开发支持。我在做实时计算相关项目时会用到，DataStream API 和 SQL 作业都能在 IDEA 里直接开发和调试</td></tr><tr><td><strong>bigdatatools-core / metastore-core</strong></td><td>大数据工具集，Hive Metastore 连接和表结构浏览</td></tr><tr><td><strong>visualizer_plugin</strong></td><td>数据可视化辅助</td></tr></tbody></table><h3 id="🔧-日常效率" tabindex="-1">🔧 日常效率 <a class="header-anchor" href="#🔧-日常效率" aria-label="Permalink to &quot;🔧 日常效率&quot;">​</a></h3><table><thead><tr><th>插件</th><th>为什么装</th></tr></thead><tbody><tr><td><strong>TranslationPlugin</strong></td><td>选中代码或英文注释，一键翻译。看英文文档或源码注释时配合使用</td></tr><tr><td><strong>GrepConsole</strong></td><td>控制台日志过滤和染色。日志一多的时候用关键词高亮或过滤，找问题比肉眼在一堆日志里翻快很多</td></tr><tr><td><strong>leetcode-editor</strong></td><td>在 IDEA 里刷 LeetCode，配置好账号直接在编辑器里做题、调试、提交</td></tr><tr><td><strong>Apipost-idea-plugin-v2</strong></td><td>API 调试插件，相当于在 IDEA 里集成了一个轻量版的 Postman。写完接口直接在 IDE 里调，不用切工具</td></tr><tr><td><strong>SequencePluginR</strong></td><td>时序图生成，根据代码执行流程自动生成时序图</td></tr></tbody></table><h3 id="🤖-ai-辅助" tabindex="-1">🤖 AI 辅助 <a class="header-anchor" href="#🤖-ai-辅助" aria-label="Permalink to &quot;🤖 AI 辅助&quot;">​</a></h3><table><thead><tr><th>插件</th><th>为什么装</th></tr></thead><tbody><tr><td><strong>lingma-jetbrains</strong>（通义灵码）</td><td>这是我现在主要的 AI 编程助手。用的 Qwen3 Coder 模型，对中文理解和国内技术栈（Spring Boot、MyBatis、Dubbo 等）的支持比 GitHub Copilot 更对味。我大部分项目都切到了 agent 模式，它可以直接读项目上下文做代码生成和修改</td></tr></tbody></table><blockquote><p>补充一句：我之前也试过 GitHub Copilot，但通义灵码在 Spring 生态下的表现确实更好一些——比如让它生成 Mapper XML、写 Service 实现这类常见操作，基本不用改就能直接用。</p></blockquote><h3 id="📦-其他" tabindex="-1">📦 其他 <a class="header-anchor" href="#📦-其他" aria-label="Permalink to &quot;📦 其他&quot;">​</a></h3><table><thead><tr><th>插件</th><th>为什么装</th></tr></thead><tbody><tr><td><strong>IntelliVuePlugin</strong></td><td>Vue 文件支持。虽然 IDEA Ultimate 自带 JavaScript 和 Vue 支持，但这个插件补了一些细节</td></tr><tr><td><strong>jboss-drools</strong></td><td>规则引擎开发，做风控或规则平台项目时用</td></tr><tr><td><strong>ant</strong></td><td>自带捆绑，偶尔跑 legacy 项目时用到</td></tr></tbody></table><hr><h2 id="四、我的-idea-日常开发流" tabindex="-1">四、我的 IDEA 日常开发流 <a class="header-anchor" href="#四、我的-idea-日常开发流" aria-label="Permalink to &quot;四、我的 IDEA 日常开发流&quot;">​</a></h2><h3 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h3><p>我本机 IDE 项目大概有 100 多个，主要分这几类：</p><ul><li><strong>Spring Boot 微服务项目</strong>：<code>big-market*</code>、<code>hfq-*</code>、<code>user-growth</code> 等，大部分是 DDD 架构</li><li><strong>框架源码学习</strong>：<code>mybatis-3</code>、<code>spring-cloud-openfeign</code>、<code>mini-spring</code>、<code>small-spring</code>、<code>nacos-examples</code>、<code>redisson</code> 等</li><li><strong>算法与面试</strong>：<code>algorithm-tutorial</code>、<code>fucking-algorithm</code>、NowCoder</li><li><strong>前端项目</strong>：<code>vue-admin-template</code>、<code>vue-element-admin</code>、<code>mall-admin-web</code></li><li><strong>Go 项目</strong> 在 GoLand 里，Java 项目在 IDEA 里，分工明确</li></ul><h3 id="快捷键记忆" tabindex="-1">快捷键记忆 <a class="header-anchor" href="#快捷键记忆" aria-label="Permalink to &quot;快捷键记忆&quot;">​</a></h3><p>IDEA 的快捷键非常多，但如果你记住下面这几组，日常开发就足够流畅了：</p><table><thead><tr><th>快捷键</th><th>作用</th><th>替代了什么</th></tr></thead><tbody><tr><td><code>Shift+Shift</code></td><td>全局搜索（文件、类、配置、操作）</td><td>几乎所有的菜单点击</td></tr><tr><td><code>Cmd+N / Ctrl+N</code></td><td>搜索类文件</td><td>不用在项目树里翻</td></tr><tr><td><code>Cmd+E</code></td><td>最近打开的文件</td><td>快速切换</td></tr><tr><td><code>Double Shift</code></td><td>Search Everywhere</td><td>任何东西都能搜</td></tr><tr><td><code>Option+Enter</code></td><td>显示建议操作（快速修复、自动导入等）</td><td>最常用的一个键</td></tr><tr><td><code>Cmd+Option+L</code></td><td>格式化代码</td><td>写完代码顺手按一下</td></tr><tr><td><code>Cmd+Shift+F</code></td><td>全局搜索文本</td><td>找关键词</td></tr><tr><td><code>Ctrl+Option+O</code></td><td>优化 import</td><td>删除未使用的 import</td></tr><tr><td><code>Cmd+B</code></td><td>跳转到定义</td><td>看源码</td></tr><tr><td><code>Option+Up</code></td><td>选中代码块</td><td>逐级扩大选中范围</td></tr><tr><td><code>Cmd+[ / Cmd+]</code></td><td>光标后退 / 前进</td><td>看完源码回到之前的位置</td></tr><tr><td><code>F2</code></td><td>跳到下一个错误</td><td>编译报错时快速定位</td></tr></tbody></table><h3 id="调试技巧" tabindex="-1">调试技巧 <a class="header-anchor" href="#调试技巧" aria-label="Permalink to &quot;调试技巧&quot;">​</a></h3><p>IDEA 的调试器是我觉得比 VS Code 强的地方之一。几个我常用的：</p><ul><li><strong>条件断点</strong>：右键断点设置条件，比如 <code>i &gt; 100 &amp;&amp; user.getName().equals(&quot;admin&quot;)</code>，只在满足条件时停下来</li><li><strong>求值表达式</strong>（<code>Option+F8</code>）：在断点停下时可以执行任意代码，修改当前变量值</li><li><strong>Drop Frame</strong>：把执行栈回退到上一帧，相当于&quot;时光倒流&quot;，可以重新走一遍流程</li><li><strong>Show Library Stack Frames</strong>：我打开了这个选项，看源码时能看到完整的调用栈</li></ul><h3 id="mybatis-代码生成配置" tabindex="-1">MyBatis 代码生成配置 <a class="header-anchor" href="#mybatis-代码生成配置" aria-label="Permalink to &quot;MyBatis 代码生成配置&quot;">​</a></h3><p>我装 MybatisX 时顺便配了一组关键字映射，让它在生成 SQL 语句时能匹配实际的方法名：</p><table><thead><tr><th>操作</th><th>匹配关键字</th></tr></thead><tbody><tr><td>插入</td><td><code>add</code>、<code>insert</code>、<code>new</code></td></tr><tr><td>删除</td><td><code>cancel</code>、<code>del</code></td></tr><tr><td>更新</td><td><code>update</code>、<code>modify</code>、<code>set</code></td></tr><tr><td>查询</td><td><code>search</code>、<code>select</code>、<code>find</code>、<code>get</code>、<code>query</code>、<code>count</code>、<code>list</code>、<code>look</code></td></tr></tbody></table><p>这样方法名叫 <code>findByUserId</code> 时自动生成 <code>select</code> 语句，<code>addUser</code> 时自动生成 <code>insert</code>——不用手动去 XML 里写，减少重复劳动。</p><hr><h2 id="五、关于-jetbrains-全家桶" tabindex="-1">五、关于 JetBrains 全家桶 <a class="header-anchor" href="#五、关于-jetbrains-全家桶" aria-label="Permalink to &quot;五、关于 JetBrains 全家桶&quot;">​</a></h2><p>除了 IDEA，我还用：</p><ul><li><strong>GoLand</strong> —— 写 Go 微服务，和 IDEA 共享快捷键和 UI，切换基本零学习成本</li><li><strong>PyCharm</strong> —— Python 脚本和数据分析</li><li><strong>DataGrip</strong> —— 所有数据库操作都在这里，智能补全 SQL、看执行计划、导出数据都很顺手。以前用 Navicat，转到 DataGrip 后回不去了</li></ul><p>这几个 IDE 共用一套 Keymap 设置，在 IDEA 里配好快捷键后，其他 IDE 自动同步，体验一致。</p><hr><h2 id="六、最后说几句" tabindex="-1">六、最后说几句 <a class="header-anchor" href="#六、最后说几句" aria-label="Permalink to &quot;六、最后说几句&quot;">​</a></h2><p>IntelliJ IDEA 对我来说更像一个&quot;Java 开发的瑞士军刀&quot;——插件生态丰富、调试器强大、重构工具靠谱。不过它也确实重（内存吃得多，启动慢），如果你只是写个简单的脚本或者前端页面，VS Code 可能是更轻量的选择。</p><p>但如果你的主力语言是 Java，特别是做 Spring Boot 微服务开发，那 IDEA 值得认真配置起来。花点时间把插件和快捷键调顺手之后，每天的编码效率提升是很明显的。</p><p>这篇文章列的都是我实际在用的，不一定适合每一个人的场景——挑有用的试试，不需要的跳过就好。</p>',63);function y(t,A,I,E,C,f){const r=s,i=l("ClientOnly");return d(),h("div",null,[D,c(i,null,{default:p(()=>{var e,a;return[(((e=t.$frontmatter)==null?void 0:e.aside)??!0)&&(((a=t.$frontmatter)==null?void 0:a.showArticleMetadata)??!0)?(d(),b(r,{key:0,article:t.$frontmatter},null,8,["article"])):m("",!0)]}),_:1}),q])}const S=n(k,[["render",y]]);export{B as __pageData,S as default};
